create table school_message (
 id bigint generated by default as identity primary key, school_id bigint not null references schedule_school(id),
 author_id bigint not null references users(id), kind varchar(20) not null check(kind in ('ANNOUNCEMENT','REMARK')),
 title varchar(200) not null, body varchar(10000) not null, student_id bigint references users(id), lesson_id bigint,
 event_date date not null, version bigint not null default 0, request_token varchar(100) not null unique,
 created_at timestamp with time zone not null default current_timestamp
);
create table message_audience(message_id bigint not null references school_message(id), student_id bigint not null references users(id), primary key(message_id,student_id));
create table message_history(id bigint generated by default as identity primary key,message_id bigint not null references school_message(id),actor_id bigint not null references users(id),old_body varchar(10000) not null,new_body varchar(10000) not null,reason varchar(1000) not null,changed_at timestamp with time zone not null default current_timestamp);
create table school_notification(id bigint generated by default as identity primary key,recipient_id bigint not null references users(id),event_key varchar(150) not null,body varchar(2000) not null,link varchar(300) not null,message_id bigint references school_message(id),student_id bigint references users(id),read_at timestamp with time zone,created_at timestamp with time zone not null default current_timestamp,unique(recipient_id,event_key));
create index school_notification_recipient on school_notification(recipient_id,created_at);
create index message_audience_student on message_audience(student_id,message_id);